import { loadFont } from "@remotion/google-fonts/Outfit";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// GRUPO CATÓIA — institucional (v5). Pedido: "muito acelerado, deixe mais desacelerado e um pouco de inversão de cor no começo".
// Voz mais lenta (velocidade 0,85 no ElevenLabs, sem corte), trocas mais longas, menos tranco de câmera, e nos números o
// "6 empresas" entra com as cores invertidas (fundo claro, letra marinho). Da v4: voz brasileira no multilingual v2. Da v3: voz nova (os 6 tópicos que o cliente pediu)
// e duas cenas desenhadas (controle de acesso e segurança eletrônica), porque as fotos de rack não mostram isso.
// Identidade do manual: azul-marinho #24224a, degradê do ícone GC, Gilroy (aqui Outfit), sempre em caixa alta.
// Tempos em segundos da voz-v5-lenta (o locutor, eleven_multilingual_v2, velocidade 0,85), usada inteira como saiu.

export const CT5_FPS = 30;
const CT_FPS = CT5_FPS;
const CT_DUR = 26.2;
export const CT5_FRAMES = Math.round(CT_DUR * CT_FPS);

const { fontFamily: FONT } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

const NAVY = "#24224a";
const LIGHT = "#ECECE7";
const WHITE = "#ffffff";
const PAL = ["#b45a9c", "#e72e79", "#e73243", "#f08214", "#efcd03", "#4ba2c0"];
const GRAD = `linear-gradient(90deg, ${PAL.join(", ")})`;
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.out(Easing.cubic);
const INOUT = Easing.inOut(Easing.cubic);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const ease = (t: number, a: number, b: number, e = OUT) => interpolate(t, [a, b], [0, 1], { ...cl, easing: e });
// mola com pouco overshoot
const sp = (t: number, at: number, damping = 18, stiffness = 120) =>
  t < at ? 0 : spring({ frame: (t - at) * CT_FPS, fps: CT_FPS, config: { damping, stiffness } });

// trocas (inícios de frase pelos silêncios da voz)
const T = {
  n: [0.06, 0.8, 1.9, 3.13],
  s2: 5.15, sist: 6.13, comp: 6.81, para: 7.35,
  lab: [9.86, 11.22, 12.68, 14.18, 15.79, 17.85],
  s4: 20.47, gc: 20.47, exc: 22.2, tudo: 22.95,
};

// o selo redondo que vem gravado no canto das fotos fica em (902, 1740): a câmera cresce a partir dele e o letreiro o cobre
const SEAL = "83.5% 90.6%";

// soco curto de câmera numa batida: cresce rápido e volta com mola
const kick = (t: number, at: number, amt = 0.05) => (t < at ? 0 : amt * Math.exp(-(t - at) * 7) * Math.sin(Math.min(Math.PI / 2, (t - at) * 18)));

const TXT: React.CSSProperties = { fontFamily: FONT, textTransform: "uppercase", whiteSpace: "nowrap", lineHeight: 1 };
const gradText = (g = GRAD): React.CSSProperties => ({ background: g, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

// texto que sobe da linha (máscara); sai descendo se `out` for dado
const Mask: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode; pad?: number }> = ({ t, at, out, children, pad = 0.12 }) => {
  const i = sp(t, at, 200, 160);
  const o = out === undefined ? 0 : ease(t, out, out + 0.16, Easing.in(Easing.cubic));
  const y = (1 - i) * 145 - o * 145;
  return (
    <div style={{ overflow: "hidden", padding: `${pad}em 0.06em`, margin: `-${pad}em 0` }}>
      <div style={{ transform: `translateY(${y.toFixed(2)}%)` }}>{children}</div>
    </div>
  );
};

// ───────── 1 · números (fundo marinho) ─────────
const ITEMS = [
  { n: "1", l: "Grupo" },
  { n: "6", l: "Empresas" },
  { n: "8", l: "Parceiros" },
  { n: "+10", l: "Soluções" },
];
const DOT_Y = 1370;
const dotX = (i: number) => 540 + (i - 1.5) * 92;

const S1: React.FC<{ t: number }> = ({ t }) => {
  if (t >= T.s2 + 0.05) return null;
  const cam = 1 + 0.16 * ease(t, 0, T.s2, INOUT) + T.n.reduce((k, at) => k + kick(t, at, 0.035), 0);
  // inversão de cor: no "6 empresas" o fundo vira claro e a letra marinho, com corte seco na batida
  const inv = t >= T.n[1] - 0.02 && t < T.n[2] - 0.02;
  const rot = [-1.2, 1.2, -1.2, 0].reduce((k, d, i) => k + d * kick(t, T.n[i], 1) * (t < T.n[i + 1] || i === 3 ? 1 : 0), 0);
  return (
    <AbsoluteFill style={{ background: inv ? LIGHT : NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)}) rotate(${rot.toFixed(3)}deg) translateY(${(-14 * lin(t, 0, T.s2)).toFixed(1)}px)`, transformOrigin: "50% 48%" }}>
        {ITEMS.map((it, i) => {
          const at = T.n[i];
          const out = i < 3 ? T.n[i + 1] - 0.2 : undefined;
          if (t < at - 0.05 || (out !== undefined && t > out + 0.2)) return null;
          const pulse = 1 + 0.06 * (1 - sp(t, at, 14, 140));
          return (
            <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 610, display: "flex", flexDirection: "column", alignItems: "center", gap: 26 }}>
              <div style={{ transform: `scale(${pulse.toFixed(3)})` }}>
                <Mask t={t} at={at} out={out} pad={0.08}>
                  <div style={{ ...TXT, fontWeight: 900, fontSize: it.n.length > 2 ? 430 : 500, letterSpacing: "-0.04em", padding: "0 0.06em", ...gradText() }}>{it.n}</div>
                </Mask>
              </div>
              <Mask t={t} at={at + 0.1} out={out === undefined ? undefined : out - 0.04}>
                <div style={{ ...TXT, fontWeight: 700, fontSize: 104, color: i === 1 ? NAVY : WHITE, letterSpacing: "0.1em", paddingLeft: "0.1em" }}>{it.l}</div>
              </Mask>
            </div>
          );
        })}
        {/* uma bolinha por número, nas cores do ícone; a última vira a próxima cena */}
        {ITEMS.map((_, i) => {
          const s = sp(t, T.n[i] + 0.05, 12, 170);
          const c = [PAL[0], PAL[1], PAL[3], PAL[5]][i];
          return <div key={i} style={{ position: "absolute", left: dotX(i) - 22, top: DOT_Y - 22, width: 44, height: 44, borderRadius: 22, background: c, transform: `scale(${s.toFixed(3)})` }} />;
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// inundação: a bolinha azul cresce e vira o fundo claro da cena 2
const Flood: React.FC<{ t: number }> = ({ t }) => {
  const a = T.s2 - 0.3;
  if (t < a || t > T.s2 + 0.1) return null;
  const r = interpolate(t, [a, T.s2], [22, 2300], { ...cl, easing: Easing.in(Easing.quad) });
  const col = t < a + 0.12 ? PAL[5] : LIGHT;
  const k = 1 + 0.16 * ease(t, 0, T.s2, INOUT);
  const cx = 540 + (dotX(3) - 540) * k, cy = 921.6 + (DOT_Y - 921.6 - 14 * lin(t, 0, T.s2)) * k;
  return <AbsoluteFill style={{ background: col, clipPath: `circle(${r.toFixed(1)}px at ${cx.toFixed(1)}px ${cy.toFixed(1)}px)` }} />;
};

// ───────── 2 · "sistemas complexos para empresas exigentes" (fundo claro) ─────────
const CARD = { x: 230, y: 880, w: 620, h: 760, r: 40 };
const MORPH = [T.lab[0] - 0.4, T.lab[0] + 0.03];

const S2: React.FC<{ t: number }> = ({ t }) => {
  if (t < T.s2 || t >= MORPH[1] + 0.05) return null;
  const cam = 1 + 0.04 * ease(t, T.s2, MORPH[0], INOUT) + kick(t, T.sist, 0.025) + kick(t, T.comp, 0.025) + kick(t, T.para, 0.015);
  const lift = ease(t, MORPH[0], MORPH[1], Easing.in(Easing.cubic));
  return (
    <AbsoluteFill style={{ background: LIGHT, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)}) translateY(${(-260 * lift).toFixed(1)}px)`, opacity: 1 - lift, transformOrigin: "50% 40%" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 268, display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
          <Mask t={t} at={T.s2 + 0.05}>
            <div style={{ ...TXT, fontWeight: 700, fontSize: 48, color: NAVY, letterSpacing: "0.08em", paddingLeft: "0.08em" }}>O Grupo Catóia desenvolve</div>
          </Mask>
          <Mask t={t} at={T.sist} pad={0.1}>
            <div style={{ ...TXT, fontWeight: 900, fontSize: 150, color: NAVY, letterSpacing: "-0.02em" }}>Sistemas</div>
          </Mask>
          <Mask t={t} at={T.comp} pad={0.1}>
            <div style={{ ...TXT, fontWeight: 900, fontSize: 150, letterSpacing: "-0.02em", ...gradText() }}>Complexos</div>
          </Mask>
          <div style={{ marginTop: 14, transform: `scale(${sp(t, T.para, 16, 150).toFixed(3)})`, background: NAVY, borderRadius: 60, padding: "16px 40px 18px" }}>
            <div style={{ ...TXT, fontWeight: 700, fontSize: 46, color: WHITE, letterSpacing: "0.06em", paddingLeft: "0.06em" }}>para empresas exigentes</div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// cartão da foto 1: entra subindo na cena 2 e cresce até virar a tela cheia da cena 3
const Card: React.FC<{ t: number }> = ({ t }) => {
  if (t < T.s2 + 0.2 || t >= T.lab[1] + 0.4) return null;
  const inn = sp(t, T.s2 + 0.3, 20, 110);
  const m = ease(t, MORPH[0], MORPH[1], INOUT);
  const x = CARD.x * (1 - m), y = (CARD.y + (1 - inn) * 900) * (1 - m);
  const w = CARD.w + (1080 - CARD.w) * m, h = CARD.h + (1920 - CARD.h) * m;
  const z = 1.0 + 0.06 * lin(t, T.s2, T.lab[1]);
  return (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: h, borderRadius: CARD.r * (1 - m), overflow: "hidden", boxShadow: m < 1 ? `0 30px 70px rgba(36,34,74,${(0.35 * (1 - m)).toFixed(2)})` : undefined, transform: `rotate(${(-2.5 * (1 - m) * inn).toFixed(2)}deg)` }}>
      <Img src={staticFile("catoia/f1-rede.png")} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 38%", transform: `scale(${z.toFixed(4)})`, transformOrigin: SEAL }} />
    </div>
  );
};

// ───────── 3 · as soluções, uma foto por frase ─────────
// tópicos na ordem do cliente; sem foto (src vazio) entra uma cena desenhada
const PHOTOS = [
  { src: "f1-rede.png", l: "Rede\nestruturada" },
  { src: "f2-telecom.png", l: "Telecomunicações" },
  { src: "", l: "Controle\nde acesso", icon: "acesso" },
  { src: "", l: "Segurança\neletrônica", icon: "seguranca" },
  { src: "f6-detalhe.png", l: "Detalhamento\ntécnico" },
  { src: "f5-organiza.png", l: "Organização e\npadronização" },
];
const S3_END = T.s4;

const TR = 0.45; // duração das transições entre fotos (mais calma na v5)

// movimento de câmera diferente por foto
const camOf = (i: number, p: number) => {
  switch (i) {
    case 1: return `scale(${(1.2 - 0.16 * p).toFixed(4)})`;
    case 2: return `translateY(${(-34 + 68 * p).toFixed(1)}px) scale(1.14)`;
    case 3: return `scale(${(1.02 + 0.16 * p).toFixed(4)}) rotate(${(-1 + 2 * p).toFixed(3)}deg)`;
    case 4: return `translateX(${(34 - 68 * p).toFixed(1)}px) scale(1.14)`;
    default: return `scale(${(1.04 + 0.14 * p).toFixed(4)})`;
  }
};
// transição de entrada de cada foto (nunca a mesma duas vezes seguidas)
const enterOf = (i: number, e: number): React.CSSProperties => {
  switch (i) {
    case 1: return { clipPath: `inset(${((1 - e) * 100).toFixed(2)}% 0 0 0)` }; // cortina de baixo para cima
    case 2: return { clipPath: `circle(${(e * 2300).toFixed(1)}px at 540px 1660px)` }; // círculo saindo do letreiro
    case 3: return { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)` }; // o desenho seguinte empurra da direita
    case 4: return { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` }; // empurra de baixo
    default: { const k = (1 - e) * 2200; return { clipPath: `polygon(${(k).toFixed(0)}px 0, 3000px 0, 3000px 1920px, ${(k - 900).toFixed(0)}px 1920px)` }; } // diagonal
  }
};

// ───────── cenas desenhadas (tópicos sem foto): peça grande no centro, fundo claro, traço que se desenha ─────────
const draw = (t: number, at: number, d = 0.5) => ease(t, at, at + d, INOUT);
const Desenho: React.FC<{ kind: string; t: number; a: number; b: number }> = ({ kind, t, a, b }) => {
  const p = lin(t, a, b);
  const pop = sp(t, a + 0.05, 16, 150);
  const L = 1000; // comprimento de traço suficiente para os caminhos
  const dash = (at: number, d = 0.5) => ({ strokeDasharray: L, strokeDashoffset: (L * (1 - draw(t, at, d))).toFixed(1) });
  return (
    <AbsoluteFill style={{ background: LIGHT, overflow: "hidden" }}>
      <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0 }}>
        <defs>
          <linearGradient id={`g-${kind}`} x1="0" x2="1" y1="0" y2="0">
            {PAL.map((c, k) => <stop key={k} offset={k / (PAL.length - 1)} stopColor={c} />)}
          </linearGradient>
          <linearGradient id={`cone-${kind}`} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0" stopColor={PAL[3]} stopOpacity={0.55} />
            <stop offset="1" stopColor={PAL[1]} stopOpacity={0} />
          </linearGradient>
        </defs>
        <g transform={`translate(540 760) scale(${((0.82 + 0.18 * pop) * (1 + 0.08 * p)).toFixed(4)}) translate(-540 -760)`}>
          {kind === "acesso" ? (
            <>
              {/* leitor biométrico na parede: corpo marinho, digital desenhada no degradê, linha de leitura passando */}
              <rect x={330} y={330} width={420} height={760} rx={70} fill={NAVY} />
              <rect x={390} y={400} width={300} height={120} rx={22} fill="#34315f" />
              <circle cx={440} cy={460} r={14} fill={PAL[5]} opacity={draw(t, a + 0.7, 0.2)} />
              <rect x={472} y={450} width={170} height={20} rx={10} fill="#4b4880" />
              <g fill="none" stroke={`url(#g-${kind})`} strokeWidth={16} strokeLinecap="round">
                {/* digital: laços fechados embaixo, cada um com uma abertura num ponto diferente */}
                {[40, 80, 120, 160].map((rr, k) => {
                  const ry = rr * 1.25, cy = 790;
                  return <path key={k} d={`M ${540 - rr} ${cy + ry * 0.55} L ${540 - rr} ${cy} A ${rr} ${ry} 0 0 1 ${540 + rr} ${cy} L ${540 + rr} ${cy + ry * (0.35 + 0.15 * k)} A ${rr} ${rr * 0.5} 0 0 1 ${540 + rr * 0.2} ${cy + ry * (0.35 + 0.15 * k) + rr * 0.45}`} style={dash(a + 0.1 + k * 0.08, 0.55)} />;
                })}
                <path d="M 540 770 L 540 830" style={dash(a + 0.1, 0.3)} />
              </g>
              {(() => {
                const ok = sp(t, a + 0.75, 13, 170);
                return (
                  <g transform={`translate(540 1010) scale(${ok.toFixed(3)})`}>
                    <circle r={52} fill={`url(#g-${kind})`} />
                    <path d="M -22 2 L -6 18 L 24 -14" fill="none" stroke={WHITE} strokeWidth={12} strokeLinecap="round" strokeLinejoin="round" />
                  </g>
                );
              })()}
              {(() => {
                const sc = (Math.sin((t - a) * 5) + 1) / 2;
                return <rect x={350} y={640 + sc * 300} width={380} height={8} rx={4} fill={PAL[5]} opacity={0.75 * draw(t, a + 0.3, 0.2)} />;
              })()}
            </>
          ) : (
            <>
              {/* câmera de segurança: suporte na parede, corpo girando devagar, feixe de detecção no degradê */}
              <g transform="translate(90 90)">
              <rect x={160} y={420} width={60} height={220} rx={16} fill={NAVY} />
              <g transform={`rotate(${(-6 + 12 * p).toFixed(2)} 230 530)`}>
                <path d={`M 470 600 L 260 1260 L 860 1260 Z`} fill={`url(#cone-${kind})`} opacity={draw(t, a + 0.25, 0.4)} />
                <rect x={200} y={510} width={140} height={40} rx={12} fill={NAVY} />
                <rect x={320} y={420} width={420} height={210} rx={46} fill={NAVY} />
                <rect x={700} y={440} width={90} height={170} rx={30} fill="#34315f" />
                <circle cx={470} cy={600} r={66} fill="#1a1838" stroke={`url(#g-${kind})`} strokeWidth={16} style={dash(a + 0.1, 0.5)} />
                <circle cx={470} cy={600} r={26} fill={PAL[5]} />
                <circle cx={640} cy={480} r={14} fill={PAL[2]} opacity={(0.4 + 0.6 * ((Math.sin((t - a) * 9) + 1) / 2)) * draw(t, a + 0.3, 0.2)} />
              </g>
              </g>
            </>
          )}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

const S3: React.FC<{ t: number }> = ({ t }) => {
  if (t < T.lab[1] - 0.1 || t >= S3_END + 0.6) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {PHOTOS.map((p, i) => {
        if (i === 0) return null;
        const a = T.lab[i] - TR * 0.6; // a troca termina logo depois do começo do tópico
        const b = i < 5 ? T.lab[i + 1] + 0.05 : S3_END + 0.6;
        if (t < a || t >= b) return null;
        const e = ease(t, a, a + TR, INOUT);
        const prog = lin(t, a, b);
        return (
          <AbsoluteFill key={i} style={{ overflow: "hidden", ...enterOf(i, e) }}>
            {p.icon ? <Desenho kind={p.icon} t={t} a={a} b={b} /> : <Img src={staticFile(`catoia/${p.src}`)} style={{ width: 1080, height: 1920, objectFit: "cover", transform: `${camOf(i, prog)} scale(${(1 + 0.035 * (1 - ease(t, a, a + 0.8))).toFixed(4)})`, transformOrigin: SEAL }} />}
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

// letreiro fixo embaixo: o bloco fica, só o texto troca (o anterior sai inteiro antes do próximo entrar)
const BLOCK = { x: 90, y: 1500, w: 900, h: 340, r: 34 };
const END_MORPH = [T.s4 - 0.32, T.s4 + 0.1];

const Letreiro: React.FC<{ t: number }> = ({ t }) => {
  if (t < T.lab[0] - 0.05 || t >= END_MORPH[1]) return null;
  const inn = sp(t, T.lab[0] - 0.02, 20, 130);
  const m = ease(t, END_MORPH[0], END_MORPH[1], INOUT);
  const x = BLOCK.x * (1 - m), y = (BLOCK.y + (1 - inn) * 420) * (1 - m);
  const w = BLOCK.w + (1080 - BLOCK.w) * m, h = BLOCK.h + (1920 - BLOCK.h) * m;
  const idx = T.lab.reduce((acc, at, i) => (t >= at - 0.02 ? i : acc), 0);
  const bar = ease(t, T.lab[idx] - 0.02, T.lab[idx] + 0.4);
  const barW = ((idx + bar) / 6) * 100;
  return (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: h, borderRadius: BLOCK.r * (1 - m), background: NAVY, overflow: "hidden", boxShadow: `0 24px 60px rgba(0,0,0,${(0.4 * (1 - m)).toFixed(2)})` }}>
      {/* barra no degradê da marca: cresce um sexto por solução */}
      <div style={{ position: "absolute", left: 0, top: 0, height: 12, width: `${barW.toFixed(2)}%`, background: GRAD, backgroundSize: "900px 12px", opacity: 1 - m }} />
      {PHOTOS.map((p, i) => {
        const at = T.lab[i] + 0.04;
        const out = i < 5 ? T.lab[i + 1] - 0.2 : END_MORPH[0] - 0.22;
        if (t < at - 0.05 || t > out + 0.2) return null;
        const lines = p.l.split("\n");
        const fs = Math.min(76, 700 / (Math.max(...lines.map((l) => l.length)) * 0.6));
        return (
          <div key={i} style={{ position: "absolute", left: 0, top: 12, width: BLOCK.w, height: BLOCK.h - 12, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6 }}>
            {lines.map((l, j) => (
              <Mask key={j} t={t} at={at + j * 0.07} out={out - (lines.length - 1 - j) * 0.03} pad={0.22}>
                <div style={{ ...TXT, fontWeight: j === 0 ? 900 : 800, fontSize: fs, color: WHITE, letterSpacing: "-0.01em", ...(j === lines.length - 1 ? gradText() : {}) }}>{l}</div>
              </Mask>
            ))}
          </div>
        );
      })}
    </div>
  );
};

// ───────── 4 · cartão final (o letreiro virou o fundo marinho) ─────────
const S4: React.FC<{ t: number }> = ({ t }) => {
  if (t < END_MORPH[1] - 0.02) return null;
  const cam = 1 + 0.12 * ease(t, T.s4, CT_DUR, INOUT) + kick(t, T.exc, 0.03);
  const lg = sp(t, T.gc - 0.05, 15, 170);
  return (
    <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})`, transformOrigin: "50% 45%" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 470, display: "flex", justifyContent: "center" }}>
          <Img src={staticFile("catoia/logo-vertical-branca.png")} style={{ width: 660, opacity: Math.min(1, lg * 2), transform: `scale(${(0.7 + 0.3 * lg).toFixed(4)})`, filter: `blur(${((1 - Math.min(1, lg * 1.4)) * 10).toFixed(1)}px)` }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1120, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
          <Mask t={t} at={T.exc} pad={0.1}>
            <div style={{ ...TXT, fontWeight: 900, fontSize: 132, letterSpacing: "-0.01em", ...gradText() }}>Excelência</div>
          </Mask>
          <Mask t={t} at={T.tudo}>
            <div style={{ ...TXT, fontWeight: 700, fontSize: 64, color: WHITE, letterSpacing: "0.08em", paddingLeft: "0.08em" }}>em tudo que faz</div>
          </Mask>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

